export function mobileGameRuleContent(game: GameCatalogEntry): MobileGameRuleContent {
  if (isMobileGameRuleSlug(game.slug)) return MOBILE_GAME_RULES_BY_SLUG[game.slug];
  throw new Error(`Missing authoritative mobile rules for game: ${game.slug}`);
}

export function isMobileGameRuleSlug(slug: string): slug is MobileGameRuleSlug {
  return (MOBILE_GAME_RULE_SLUGS as readonly string[]).includes(slug);
}

function rules(content: MobileGameRuleContent): MobileGameRuleContent {
  return Object.freeze({
    ...content,
    shortSummary: Object.freeze([...content.shortSummary]) as MobileGameRuleContent["shortSummary"],
  });
}
